def longest_mountain(arr: List[int]) -> int:
    if len(arr) < 3:
        return 0

    up = [1] * len(arr)
    down = [1] * len(arr)

    # Compute up array
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            up[i] = up[i-1] + 1
        else:
            up[i] = 1

    # Compute down array
    for i in range(len(arr)-2, -1, -1):
        if arr[i] > arr[i+1]:
            down[i] = down[i+1] + 1
        else:
            down[i] = 1

    max_length = 0
    for i in range(len(arr)):
        if up[i] >= 2 and down[i] >= 2:
            current_mountain = up[i] + down[i] - 1
            if current_mountain > max_length:
                max_length = current_mountain

    return max_length
